"use client";
import { type CSSProperties, type ReactNode, useEffect, useRef, useState } from "react";

export interface CustomCursorProps {
  children: ReactNode;
  size?: number;
  duration?: number;
  color?: string;
  textColor?: string;
  /** Attribute to read from hovered ancestors, e.g. data-cursor-label="View project". */
  labelAttribute?: string;
  className?: string;
  style?: CSSProperties;
  height?: CSSProperties["height"];
}
/** A cursor scoped to its content, with native input preserved on touch and reduced motion. */
export function CustomCursor({
  children,
  size = 12,
  duration = 0.18,
  color = "#111",
  textColor = "#fff",
  labelAttribute = "data-cursor-label",
  className,
  style,
  height,
}: CustomCursorProps) {
  const host = useRef<HTMLDivElement>(null),
    cursor = useRef<HTMLDivElement>(null);
  const options = useRef({ duration, labelAttribute });
  options.current = { duration, labelAttribute };
  const [active, setActive] = useState(false),
    [label, setLabel] = useState("");
  useEffect(() => {
    const root = host.current,
      marker = cursor.current;
    if (!root || !marker) return;
    const reduced = matchMedia("(prefers-reduced-motion: reduce)"),
      coarse = matchMedia("(pointer: coarse)");
    let frame = 0,
      last = 0,
      inside = false,
      x = 0,
      y = 0,
      targetX = 0,
      targetY = 0;
    const draw = (now: number) => {
      frame = 0;
      if (!inside) return;
      const dt = Math.min(64, last ? now - last : 16);
      last = now;
      const ease = 1 - Math.exp(-dt / Math.max(1, options.current.duration * 350));
      x += (targetX - x) * ease;
      y += (targetY - y) * ease;
      marker.style.transform = `translate3d(${x}px,${y}px,0) translate(-50%,-50%)`;
      if (Math.abs(targetX - x) + Math.abs(targetY - y) > 0.05) frame = requestAnimationFrame(draw);
    };
    const clear = () => {
      inside = false;
      setActive(false);
      cancelAnimationFrame(frame);
      frame = 0;
      last = 0;
    };
    const move = (event: PointerEvent) => {
      if (reduced.matches || coarse.matches || event.pointerType === "touch") {
        clear();
        return;
      }
      const rect = root.getBoundingClientRect();
      targetX = event.clientX - rect.left;
      targetY = event.clientY - rect.top;
      if (!inside) {
        x = targetX;
        y = targetY;
        inside = true;
        setActive(true);
      }
      let target = event.target instanceof Element ? event.target : null,
        caption = "";
      while (target && root.contains(target)) {
        caption = target.getAttribute(options.current.labelAttribute) ?? "";
        if (caption || target === root) break;
        target = target.parentElement;
      }
      setLabel(caption);
      if (!frame) frame = requestAnimationFrame(draw);
    };
    const visibility = () => {
      if (document.hidden) clear();
    };
    const observer = new IntersectionObserver((entries) => {
      if (!entries[0]?.isIntersecting) clear();
    });
    observer.observe(root);
    root.addEventListener("pointermove", move);
    root.addEventListener("pointerleave", clear);
    reduced.addEventListener("change", clear);
    coarse.addEventListener("change", clear);
    document.addEventListener("visibilitychange", visibility);
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      root.removeEventListener("pointermove", move);
      root.removeEventListener("pointerleave", clear);
      reduced.removeEventListener("change", clear);
      coarse.removeEventListener("change", clear);
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return (
    <div
      ref={host}
      data-zeus-custom-cursor
      data-active={active}
      className={className}
      style={{
        position: "relative",
        isolation: "isolate",
        width: "100%",
        height: height ?? "var(--zeus-animation-height, 480px)",
        overflow: "hidden",
        ...style,
      }}
    >
      <style>{`[data-zeus-custom-cursor][data-active="true"], [data-zeus-custom-cursor][data-active="true"] * {cursor:none}`}</style>
      {children}
      <div
        ref={cursor}
        data-cursor-marker
        aria-hidden
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          zIndex: 50,
          pointerEvents: "none",
          opacity: active ? 1 : 0,
          background: color,
          color: textColor,
          borderRadius: 999,
          minWidth: Math.max(1, size),
          minHeight: Math.max(1, size),
          padding: label ? "12px 18px" : 0,
          fontSize: 14,
          fontWeight: 500,
          lineHeight: "20px",
          whiteSpace: "nowrap",
          transition: "opacity .12s, padding .18s",
          willChange: "transform",
        }}
      >
        {label}
      </div>
    </div>
  );
}
